package com.jono.app;
import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.google.firebase.auth.FirebaseAuth;
public class LoginActivity extends AppCompatActivity { EditText email,password; public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this); l.setOrientation(LinearLayout.VERTICAL); l.setPadding(32,64,32,32); TextView t=new TextView(this); t.setText("Jono\nLogin"); t.setTextSize(28); email=new EditText(this); email.setHint("Email"); password=new EditText(this); password.setHint("Password"); password.setInputType(129); Button x=new Button(this); x.setText("Login"); l.addView(t);l.addView(email);l.addView(password);l.addView(x);setContentView(l); x.setOnClickListener(v->FirebaseAuth.getInstance().signInWithEmailAndPassword(email.getText().toString(),password.getText().toString()).addOnCompleteListener(q->{if(q.isSuccessful())finish();else Toast.makeText(this,"Login failed",Toast.LENGTH_SHORT).show();})); } }
